class AgeError(Exception):
    def __init__(self, age):
        self.age = age
        super().__init__(f"Invalid age: {age}")

def check_age(age):
    if age < 0 or age > 150:
        raise AgeError(age)
    return f"Age {age} is valid"

try:
    result = check_age(200)
except AgeError as e:
    print(f"Caught: {e}")
    print(f"Invalid value was: {e.age}")
